INSERT OR IGNORE INTO blog_posts (slug, title, excerpt, content, thumbnail_url, author_doctor_slug, meta_description, meta_keywords, is_published)
VALUES
('denture-vs-implant-overdenture-guide',
 '틀니가 자꾸 흘러내린다면 — 임플란트 틀니(오버덴쳐)라는 선택지',
 '헐거워진 틀니 때문에 식사가 두려우신가요? 일반 틀니와 임플란트 틀니(오버덴쳐)의 차이, 비용 구조, 보험 적용까지 대표원장이 정리했습니다.',
 '<h2>틀니가 헐거워지는 것은 당연한 일입니다</h2><p>틀니는 잇몸 위에 얹혀 있는 장치입니다. 문제는 치아가 없는 잇몸뼈가 <strong>해마다 조금씩 흡수되어 낮아진다</strong>는 점입니다. 처음엔 잘 맞던 틀니도 몇 년 지나면 뼈가 줄어든 만큼 헐거워지고, 음식을 씹을 때마다 들썩이며 잇몸을 아프게 합니다.</p><p>접착제로 버티는 것은 임시방편입니다. 헐거운 틀니로 계속 씹으면 잇몸뼈 흡수가 오히려 가속되는 악순환이 생깁니다.</p><h2>임플란트 틀니(오버덴쳐)란?</h2><p>잇몸뼈에 <strong>임플란트 2~4개를 심고, 그 위에 똑딱단추처럼 틀니를 끼우는 방식</strong>입니다. 틀니가 임플란트에 고정되기 때문에 식사 중 흘러내리거나 들썩이지 않고, 씹는 힘도 일반 틀니의 2배 이상으로 회복됩니다.</p><h3>전체 임플란트와 무엇이 다른가요?</h3><ul><li><strong>전체 임플란트(풀아치)</strong> — 치아 하나하나를 임플란트로 대체. 씹는 힘이 가장 좋지만 8~12개 식립이 필요해 비용과 수술 부담이 큼</li><li><strong>임플란트 틀니(오버덴쳐)</strong> — 임플란트 2~4개로 틀니를 고정. 비용은 전체 임플란트의 절반 이하, 탈착식이라 세척 관리가 쉬움</li><li><strong>일반 틀니</strong> — 수술 없이 가능하지만 유지력·씹는 힘의 한계가 뚜렷함</li></ul><h2>65세 이상이라면 보험 혜택을 확인하세요</h2><p>만 65세 이상은 <strong>틀니와 치과 임플란트(1인당 2개)에 건강보험이 적용</strong>됩니다. 보험 임플란트 2개를 아래턱에 식립하고 오버덴쳐로 연결하는 조합은 비용 부담을 크게 낮추면서 씹는 기능을 회복하는 현실적인 설계입니다.</p><h2>어떤 분께 오버덴쳐를 권하나요?</h2><ul><li>기존 틀니가 헐거워 식사가 힘든 분</li><li>전체 임플란트는 비용·건강상 부담스러운 분</li><li>잇몸뼈 흡수가 진행되어 일반 틀니 유지가 어려운 분</li><li>탈착 세척이 가능한 관리 편의를 원하시는 분</li></ul><p>대구365치과는 CT로 잔존 뼈량을 분석해 일반 틀니·오버덴쳐·전체 임플란트 중 어떤 설계가 맞는지 비용까지 비교해 설명드립니다. 어르신 모시고 오시는 보호자분께도 치료 계획을 함께 안내드립니다.</p><p>관련 정보: <a href="/dictionary/overdenture">오버덴쳐(임플란트 틀니)</a> · <a href="/dictionary/rpd">부분틀니</a> · <a href="/dictionary/dental-implant">임플란트</a> 용어사전</p>',
 '/static/images/hero-interior.jpg',
 'kim-seongju',
 '헐거운 틀니의 원인과 해결책 — 임플란트 틀니(오버덴쳐)의 원리, 전체 임플란트·일반 틀니와의 비교, 만 65세 이상 보험 적용까지. 대구 임플란트 틀니는 대구365치과.',
 '임플란트 틀니, 오버덴쳐, 틀니 헐거움, 틀니 vs 임플란트, 대구 틀니',
 1),

('orthodontic-retainer-complete-guide',
 '교정 끝났다고 끝이 아닙니다 — 유지장치(리테이너), 언제까지 껴야 할까?',
 '수년의 교정이 끝난 뒤 유지장치를 소홀히 하면 치아는 원래 자리로 돌아갑니다. 유지장치 종류, 착용 기간, 잃어버렸을 때 대처법을 교정과 전문의가 안내합니다.',
 '<h2>치아는 원래 자리를 기억합니다</h2><p>교정으로 치아를 움직이면 치아를 둘러싼 잇몸 섬유와 뼈는 새 위치에 완전히 적응하기까지 오랜 시간이 걸립니다. 그 사이 치아는 <strong>고무줄처럼 원래 자리로 돌아가려는 성질(회귀 현상)</strong>을 보입니다. 유지장치는 이 회귀를 막는 유일한 수단입니다.</p><p>실제로 교정 재치료 환자의 상당수가 "유지장치를 안 꼈더니 몇 달 만에 앞니가 틀어졌다"는 케이스입니다. 수년의 교정과 비용이 유지장치 소홀로 무너지는 것입니다.</p><h2>유지장치의 두 종류</h2><h3>1. 고정식 유지장치</h3><p>앞니 안쪽에 가는 철사를 접착해 두는 방식입니다. <strong>착용을 잊을 일이 없다</strong>는 것이 최대 장점이지만, 철사 주변에 치석이 쉽게 쌓여 치실·치간칫솔 관리가 필수입니다. 간혹 한쪽이 떨어진 것을 모르고 지내다 치아가 틀어지는 경우가 있으니, 혀로 만져봐서 들뜬 느낌이 있으면 바로 내원하세요.</p><h3>2. 가철식 유지장치</h3><p>투명 마우스피스형 또는 철사+플라스틱형으로, 빼고 낄 수 있는 장치입니다. 식사·양치 시 빼기 때문에 위생 관리가 쉬운 대신 <strong>착용 성실도가 전부</strong>입니다.</p><h2>언제까지 껴야 하나요?</h2><ol><li><strong>교정 직후 6개월~1년</strong> — 하루 20시간 이상(식사·양치 외 종일) 착용</li><li><strong>이후 1~2년</strong> — 수면 시간 착용으로 단계적 축소</li><li><strong>그 이후</strong> — 주 2~3회 야간 착용을 가능한 한 오래 유지</li></ol><p>교정과에서는 "유지장치는 평생"이라고 말합니다. 나이가 들며 치아는 교정 여부와 무관하게 조금씩 움직이기 때문에, 주 몇 회의 야간 착용을 습관으로 유지하는 것이 가장 안전합니다.</p><h2>잃어버렸거나 안 맞을 때</h2><p>가철식 유지장치를 분실했다면 <strong>최대한 빨리(1~2주 내) 재제작</strong>해야 합니다. 몇 주만 지나도 치아가 미세하게 움직여 새 장치가 필요해집니다. 오래 방치해 장치가 안 들어간다면 부분 재교정이 필요할 수 있으니 자가 판단으로 억지로 끼우지 마세요.</p><p>대구365치과 교정과는 유지 단계까지 정기 체크를 계획에 포함하며, 장치 파손·분실 시 빠른 재제작으로 회귀를 최소화합니다.</p><p>관련 정보: <a href="/dictionary/retainer">유지장치(리테이너)</a> · <a href="/dictionary/malocclusion">부정교합</a> 용어사전</p>',
 '/static/images/smile-portrait.jpg',
 'kim-jinduk',
 '교정 후 유지장치(리테이너) 완벽 가이드 — 고정식 vs 가철식 비교, 단계별 착용 기간, 분실 시 대처법까지 교정과 전문의가 정리. 대구 교정치과는 대구365치과.',
 '유지장치, 리테이너, 교정 유지장치 기간, 리테이너 분실, 대구 교정치과',
 1),

('extraction-vs-nonextraction-ortho',
 '교정할 때 이를 꼭 빼야 하나요? — 발치 교정 vs 비발치 교정, 결정 기준',
 '"이 4개를 빼야 합니다"라는 말에 놀라셨나요? 발치가 필요한 경우와 비발치로 가능한 경우, 무리한 비발치 교정의 부작용까지 교정과 전문의가 기준을 공개합니다.',
 '<h2>발치 여부는 "공간 계산"으로 결정됩니다</h2><p>교정의 본질은 치아를 가지런히 배열할 <strong>공간을 확보하는 일</strong>입니다. 치아 크기의 합이 턱뼈 공간보다 크면 어딘가에서 공간을 만들어야 하고, 그 방법이 발치냐 비발치냐의 갈림길입니다.</p><h2>발치 교정이 필요한 대표적인 경우</h2><ul><li><strong>심한 돌출입</strong> — 앞니를 안으로 넣을 공간이 필요. 발치 공간을 이용해 입매를 개선</li><li><strong>심한 총생(삐뚤빼뚤)</strong> — 치아 크기 합과 턱 공간의 차이가 큰 경우</li><li><strong>교합 관계 교정</strong> — 위아래 어금니 맞물림을 맞추기 위해 비대칭 발치가 필요한 경우</li></ul><p>보통 소구�� (작은어금니) 4개를 발치하며, 씹는 기능에서 역할이 상대적으로 작고 발치 공간 활용이 효율적이기 때문입니다.</p><h2>비발치로 가능한 경우</h2><ul><li>공간 부족이 경미한 경우(수 mm 이내)</li><li>치열 폭 확장이나 어금니 후방 이동으로 공간 확보가 가능한 경우</li><li>치아 옆면을 미세하게 다듬는 IPR(치간 삭제)로 해결되는 경우</li></ul><h2>무리한 비발치 교정의 부작용</h2><p>"이를 빼기 싫다"는 마음은 당연합니다. 하지만 공간이 부족한데 억지로 비발치로 진행하면 <strong>앞니가 바깥으로 밀려 입이 더 돌출</strong>되거나, 치아가 잇몸뼈 범위를 벗어나 <strong>잇몸 퇴축·치근 노출</strong>이 생길 수 있습니다. 가지런하지만 입이 나와 보이는 결과는 성공한 교정이 아닙니다.</p><h2>정확한 진단이 논쟁을 끝냅니다</h2><p>발치 여부는 의사의 성향이 아니라 <strong>측모두부계측(세팔로) 분석과 공간 분석 수치</strong>로 결정되어야 합니다. 대구365치과 교정과는 세팔로·3D 스캔 데이터로 공간 부족량을 수치로 보여드리고, 발치·비발치 각각의 예상 결과를 비교 설명한 뒤 함께 결정합니다.</p><p>관련 정보: <a href="/dictionary/extraction-orthodontics">발치 교정</a> · <a href="/dictionary/non-extraction-orthodontics">비발치 교정</a> · <a href="/dictionary/malocclusion">부정교합</a> 용어사전</p>',
 '/static/images/wide-hallway.jpg',
 'kim-jinduk',
 '교정 발치 결정 기준 — 발치가 필요한 3가지 경우, 비발치 가능 조건, 무리한 비발치 교정의 부작용(돌출·잇몸 퇴축)까지 교정과 전문의가 설명. 대구 교정은 대구365치과.',
 '발치 교정, 비발치 교정, 교정 이 빼야 하나, 돌출입 교정, 대구 교정치과',
 1),

('inlay-crown-cavity-treatment-choice',
 '충치 치료, 레진·인레이·크라운 중 뭘로? — 크기별 선택 기준',
 '같은 충치인데 어떤 병원은 레진, 어떤 병원은 크라운을 권한다면? 충치 크기에 따른 치료법 선택 기준을 보존과 전문의가 명확히 정리했습니다.',
 '<h2>치료법은 "남은 치아의 양"이 결정합니다</h2><p>충치 치료의 원칙은 감염 부위를 제거하고, <strong>남은 치아가 씹는 힘을 견딜 수 있는 방법으로 수복</strong>하는 것입니다. 충치가 클수록 남는 치아가 적어지고, 그만큼 더 든든한 수복물이 필요합니다.</p><h2>크기별 선택 기준</h2><h3>1. 작은 충치 → 레진</h3><p>충치가 법랑질~상아질 초입에 머무는 경우, 감염 부위만 최소 삭제하고 치아색 레진을 당일 충전합니다. 앞니·좁은 범위 충치의 1순위이며, 광중합 레진 충전은 조건에 따라 건강보험이 적용되는 경우도 있습니다.</p><h3>2. 중간 크기 충치 → 인레이</h3><p>충치가 씹는 면을 넓게 차지해 레진으로는 강도가 부족한 경우입니다. 본을 떠 기공소에서 <strong>세라믹·골드로 정밀 제작한 수복물을 접착</strong>하며, 씹는 면 모양과 인접 치아와의 접촉면을 정확히 재현합니다. 충치가 씹는 면을 넘어 교두(치아 봉우리)까지 침범했다면 교두를 덮는 온레이로 확장합니다.</p><h3>3. 큰 충치·신경치료 후 → 크라운</h3><p>충치가 치아의 절반 가까이 침범했거나 신경치료를 마친 치아는 <strong>치아 전체를 씌우는 크라운</strong>이 필요합니다. 남은 치아 벽이 얇아 부분 수복으로는 파절을 막을 수 없기 때문입니다.</p><h2>"과잉진료 아닌가요?" 판단하는 법</h2><ul><li>충치 사진이나 X-ray를 <strong>직접 보여주며 설명</strong>하는지 확인하세요</li><li>"레진으로는 왜 안 되는지" 이유를 물었을 때 남은 치아량 기준으로 답하는지 보세요</li><li>반대로 큰 충치를 무조건 레진으로 때우는 것도 좋은 치료가 아닙니다 — 얼마 못 가 깨지거나 재발합니다</li></ul><h2>대구365치과의 원칙</h2><p>대구365치과 자연치아살리기센터는 <strong>"가능한 한 적게 깎고, 필요한 만큼 든든하게"</strong>를 원칙으로 합니다. 구강 카메라로 충치 상태를 직접 보여드리고, 레진·인레이·크라운 각각의 예상 수명과 비용을 비교해 선택을 도와드립니다. 원내 디지털 기공 시스템으로 인레이·크라운 제작 정밀도를 자체 관리합니다.</p><p>관련 정보: <a href="/dictionary/inlay">인레이</a> · <a href="/dictionary/onlay">온레이</a> · <a href="/dictionary/composite-resin">레진</a> · <a href="/dictionary/crown">크라운</a> 용어사전</p>',
